"""Local copy of the harness ranking, parameterised by memory path (probe only)."""
import json, math, re
from collections import Counter
from pathlib import Path

MAX_CHARS = 30000
NGRAM_SIZE = 2

def _ngrams(text):
    text = re.sub(r"\s+", " ", text).strip()
    return Counter(text[i:i+NGRAM_SIZE] for i in range(len(text)-NGRAM_SIZE+1))

def _idf(documents):
    df = Counter()
    for d in documents: df.update(d.keys())
    total = max(len(documents),1)
    return {g: math.log((total+1)/(c+1))+1.0 for g,c in df.items()}

def _wnorm(d, w):
    return math.sqrt(sum((c*w.get(g,1.0))**2 for g,c in d.items()))

def _cos(q,d,w,qn,dn):
    if not qn or not dn: return 0.0
    return sum(c*d.get(g,0)*w.get(g,1.0)**2 for g,c in q.items())/(qn*dn)

def rank(memory_path, input_text):
    examples = json.loads(Path(memory_path).read_text())["examples"]
    questions = [e.get("raw_question", e["input"]) for e in examples]
    documents = [_ngrams(q) for q in questions]
    weights = _idf(documents)
    query = _ngrams(input_text)
    qn = _wnorm(query, weights)
    scores = [_cos(query, d, weights, qn, _wnorm(d, weights)) for d in documents]
    ranking = sorted(range(len(examples)), key=lambda i: (-scores[i], i))
    return examples, questions, scores, ranking

def delivered_text(memory_path, input_text):
    examples, questions, scores, ranking = rank(memory_path, input_text)
    parts, total = [], 0
    for i in ranking:
        part = f"Q: {questions[i]}\nA: {examples[i]['target']}"
        if total + len(part) > MAX_CHARS: continue
        parts.append(part); total += len(part)+2
    return "\n\n".join(parts)
