"""LawBench answer parsing helpers, mirroring the evaluator and the harness conventions."""
import json, re

def extract_final_answer(text):
    """Mirror of benchmark.answers.extract_json_field for the final_answer field."""
    if not text: return ""
    try:
        data = json.loads(text)
        if isinstance(data, dict): return str(data.get("final_answer", ""))
    except Exception: pass
    for m in re.finditer(r"```(?:json)?\s*([\s\S]*?)\s*```", text):
        try:
            data = json.loads(m.group(1))
            if isinstance(data, dict): return str(data.get("final_answer", ""))
        except Exception: pass
    for start in range(len(text)):
        if text[start] != "{": continue
        depth, pos, in_str = 1, start+1, False
        while pos < len(text) and depth > 0:
            c = text[pos]
            if c == '"' and (pos == 0 or text[pos-1] != "\\"): in_str = not in_str
            elif not in_str: depth += 1 if c == "{" else (-1 if c == "}" else 0)
            pos += 1
        if depth == 0:
            cand = re.sub(r",\s*([\]}])", r"\1", text[start:pos])
            try:
                data = json.loads(cand)
                if isinstance(data, dict): return str(data.get("final_answer", ""))
            except Exception: pass
    m = re.findall(rf'"final_answer"\s*:\s*"([^"]*)"', text)
    return m[-1] if m else ""

def parse_charges(prediction):
    """Mirror of benchmark evaluators.eval_lawbench.parse_charges."""
    text = extract_final_answer(prediction).strip()
    match = re.search(r"\[罪名\](.*?)(?:<eoa>|$)", text)
    if match: text = match.group(1).strip()
    elif "罪名:" in text: text = text.split("罪名:")[-1]
    text = re.sub(r"<eoa>.*", "", text).strip()
    for sep in [";", "；", ",", "，", "、"]:
        if sep in text: return {p.strip() for p in text.split(sep) if p.strip()}
    return {text} if text else set()

def components(answer):
    """Mirror of solver.answer_space.components."""
    for sep in (";", "；", ",", "，", "、", "|", "/"):
        if sep in answer: return [p.strip() for p in answer.split(sep) if p.strip()]
    return [answer.strip()] if answer.strip() else []
