"""Offline replay of a recorded run's final messages through candidate answer rules."""
import json, sys, re
from pathlib import Path
sys.path.insert(0, '/workspace')
from benchmark.evaluate import score

def message_text(path):
    d = json.load(open(path))
    msgs = d.get('messages', [])
    asst = [m for m in msgs if m.get('role') == 'assistant' and _text(m).strip()]
    if not asst:
        return None, d
    return _text(asst[-1]), d

def _text(m):
    c = m.get('content')
    if isinstance(c, str):
        return c
    if isinstance(c, list):
        return ''.join(b if isinstance(b, str) else (b or {}).get('text', '') for b in c)
    return ''

def pre_answer(d):
    """The answer the agent gave before grounding, from the adjudication side call."""
    for call in d.get('side_calls') or []:
        for m in call:
            c = _text(m)
            if '## The answer the agent gave' in c:
                tail = c.split('## The answer the agent gave', 1)[1]
                tail = tail.split('## How the training memory spells answers', 1)[0]
                return tail.strip()
    return None

def load_rows(run_dir, task):
    rows = [json.loads(l) for l in open(Path(run_dir) / 'results' / 'samples.jsonl')]
    return [r for r in rows if r['task'] == task]

def conv_path(run_dir, task, r):
    return str(Path(run_dir) / task / 'conversations' / f"{r['example_index']:04d}" / f"sample-{r['sample_index']}.json")

def baseline_check(run_dir, task):
    """Score the recorded messages; must reproduce the recorded was_correct."""
    agree = 0; n = 0; diffs = []
    for r in load_rows(run_dir, task):
        text, d = message_text(conv_path(run_dir, task, r))
        if text is None:
            continue
        got = score(task, {'target': r['target']}, text, 'ok')['was_correct']
        n += 1
        if got == r['was_correct']:
            agree += 1
        else:
            diffs.append((r['example_index'], r['sample_index'], r['was_correct'], got))
    return agree, n, diffs
