"""Replay the harness's answer-space rules on a recorded run's own messages."""
import json, sys, re
from pathlib import Path
sys.path.insert(0, '/workspace/harness/solver')
sys.path.insert(0, '/tmp/r8')

import answer_space, adjudication, resolution
import lb

def set_memory(memory_path):
    answer_space.MEMORY_PATH = memory_path

def index(memory_path):
    return answer_space.build_index(memory_path)

def text_of(m):
    c = m.get('content')
    if isinstance(c, str): return c
    if isinstance(c, list): return ''.join(b if isinstance(b, str) else (b or {}).get('text','') for b in c)
    return ''

def pre_grounding_answer(conv):
    """The answer the agent gave, taken from the adjudication side call prompt."""
    for call in conv.get('side_calls') or []:
        for m in call:
            t = text_of(m)
            if '## The answer the agent gave' in t:
                tail = t.split('## The answer the agent gave', 1)[1]
                tail = tail.split('## How the training memory spells answers', 1)[0]
                return tail.strip()
    return None

def side_rewrites(conv):
    """The rewrites the adjudicator returned, if any."""
    for call in conv.get('side_calls') or []:
        for m in call:
            if m.get('role') == 'assistant':
                try:
                    data = json.loads(text_of(m))
                    if isinstance(data, dict) and 'rewrites' in data:
                        return [(r['from'], r['to']) for r in data['rewrites']
                                if isinstance(r, dict) and 'from' in r and 'to' in r]
                except Exception:
                    pass
    return None

def rebuild_message(conv, answer):
    """A message carrying the given answer value in its final_answer field."""
    return json.dumps({"reasoning": "", "final_answer": answer}, ensure_ascii=False)
