"""Marginal effect of complete_compound inside the real pipeline order."""
import glob, json, sys, collections
sys.path.insert(0, '/tmp/r8'); sys.path.insert(0, '/workspace'); sys.path.insert(0, '/workspace/harness/solver')
import answer_space, adjudication, resolution
from benchmark.evaluate import score

RUN = '/workspace/runs'
TASKS = ('LawBench', 'USPTO', 'Symptom2Disease')


def text_of(m):
    c = m.get('content')
    if isinstance(c, str): return c
    if isinstance(c, list): return ''.join(b if isinstance(b, str) else (b or {}).get('text', '') for b in c)
    return ''


def pre_answer(conv):
    for call in conv.get('side_calls') or []:
        for m in call:
            t = text_of(m)
            if '## The answer the agent gave' in t:
                tail = t.split('## The answer the agent gave', 1)[1]
                return tail.split('## How the training memory spells answers', 1)[0].strip()
    return None


def side_rewrites(conv):
    for call in conv.get('side_calls') or []:
        for m in call:
            if m.get('role') == 'assistant':
                try:
                    data = json.loads(text_of(m))
                except Exception:
                    continue
                if isinstance(data, dict) and 'rewrites' in data:
                    return [(r['from'], r['to']) for r in data['rewrites']
                            if isinstance(r, dict) and 'from' in r and 'to' in r]
    return None


def msg(answer):
    return json.dumps({"reasoning": "", "final_answer": answer}, ensure_ascii=False)


total = collections.Counter()
for run_dir in sorted(glob.glob(f'{RUN}/*/')):
    if not glob.glob(run_dir + 'LawBench/memory.json'):
        continue
    name = run_dir.rstrip('/').split('/')[-1][:12]
    per = collections.Counter()
    for task in TASKS:
        path = run_dir + f'{task}/memory.json'
        index = answer_space.build_index(path)
        conventions = answer_space.edge_conventions(answer_space.stored_values(path))
        for row in (json.loads(l) for l in open(run_dir + 'results/samples.jsonl')):
            if row['task'] != task or row['status'] != 'ok':
                continue
            conv = json.load(open(
                f"{run_dir}{task}/conversations/{row['example_index']:04d}/sample-{row['sample_index']}.json"))
            raw = pre_answer(conv)
            if raw is None:
                continue
            rewrites = side_rewrites(conv) or []
            answer, _ = adjudication.rewrite(raw, adjudication.accepted(rewrites, index[0]))
            answer, _ = answer_space.canonicalize(answer, index)
            answer, _ = answer_space.trim_trailing(answer, index, conventions)
            completed, applied = answer_space.complete_compound(answer, index)
            if not applied:
                continue
            before = score(task, {'target': row['target']}, msg(answer), 'ok')['was_correct']
            after = score(task, {'target': row['target']}, msg(completed), 'ok')['was_correct']
            per['fired'] += applied
            if after and not before:
                per['win'] += 1
                print('WIN', name, task, row['example_index'], row['sample_index'], answer, '->', completed, '| target', row['target'])
            elif before and not after:
                per['loss'] += 1
                print('LOSS', name, task, row['example_index'], row['sample_index'], answer, '->', completed, '| target', row['target'])
            else:
                per['nochange'] += 1
    total.update(per)
    print(name, dict(per), flush=True)
print('TOTAL', dict(total))
PY
