"""Effect of a value-count guard on the adjudicator's rewrites, with/without completion."""
import glob, json, sys, collections
sys.path.insert(0, '/tmp/r8'); sys.path.insert(0, '/workspace'); sys.path.insert(0, '/workspace/harness/solver')
import answer_space, adjudication
from benchmark.evaluate import score

RUN = '/workspace/runs'
TASKS = ('LawBench', 'USPTO', 'Symptom2Disease')


def text_of(m):
    c = m.get('content')
    if isinstance(c, str): return c
    if isinstance(c, list): return ''.join(b if isinstance(b, str) else (b or {}).get('text', '') for b in c)
    return ''


def pre_answer(conv):
    for call in conv.get('side_calls') or []:
        for m in call:
            t = text_of(m)
            if '## The answer the agent gave' in t:
                return t.split('## The answer the agent gave', 1)[1].split('## How the training memory spells answers', 1)[0].strip()
    return None


def side_rewrites(conv):
    for call in conv.get('side_calls') or []:
        for m in call:
            if m.get('role') == 'assistant':
                pairs = adjudication.rewrites(text_of(m))
                if pairs:
                    return pairs
    return None


def msg(a):
    return json.dumps({"reasoning": "", "final_answer": a}, ensure_ascii=False)


def count_values(text):
    return len(answer_space.components(text))


def apply_rewrites(text, pairs, guard):
    applied = []
    for source, target in pairs:
        if source not in text:
            continue
        if guard and count_values(text.replace(source, target, 1)) > count_values(text):
            continue
        text = text.replace(source, target, 1)
        applied.append((source, target))
    return text


runs = sorted(d for d in glob.glob(f'{RUN}/*/') if glob.glob(d + 'LawBench/memory.json'))
for guard in (False, True):
    for completion in (False, True):
        total = collections.Counter()
        for rd in runs:
            for task in TASKS:
                path = rd + f'{task}/memory.json'
                index = answer_space.build_index(path)
                conventions = answer_space.edge_conventions(answer_space.stored_values(path))
                for row in (json.loads(l) for l in open(rd + 'results/samples.jsonl')):
                    if row['task'] != task or row['status'] != 'ok':
                        continue
                    conv = json.load(open(f"{rd}{task}/conversations/{row['example_index']:04d}/sample-{row['sample_index']}.json"))
                    raw = pre_answer(conv)
                    if raw is None:
                        continue
                    pairs = adjudication.accepted(side_rewrites(conv) or [], index[0])
                    answer = apply_rewrites(raw, pairs, guard)
                    answer, _ = answer_space.canonicalize(answer, index)
                    answer, _ = answer_space.trim_trailing(answer, index, conventions)
                    if completion:
                        answer, _ = answer_space.complete_compound(answer, index)
                    got = score(task, {'target': row['target']}, msg(answer), 'ok')['was_correct']
                    total['correct'] += got
                    if got and not row['was_correct']: total['win'] += 1
