                        total['loss'] += 1
                        total.setdefault('losses', []).append((rd.split('/')[-2][:12], task, row['example_index'], row['sample_index'], answer, row['target']))
        print('guard', guard, 'completion', completion, 'correct', total['correct'], 'wins', total['win'], 'losses', total['loss'])
        for l in total.get('losses', [])[:6]:
            print('    LOSS', l)
