"""Attribution of the new run's movement to complete_compound, on the run's own messages."""
import json, sys, collections
sys.path.insert(0, '/tmp/r8'); sys.path.insert(0, '/workspace'); sys.path.insert(0, '/workspace/harness/solver')
import answer_space, adjudication
from benchmark.evaluate import score

NEW = '/workspace/runs/4621bcdd04680865c575918afaf12e57c1d972f0'
TASKS = ('USPTO', 'Symptom2Disease', 'LawBench')


def text_of(m):
    c = m.get('content')
    if isinstance(c, str): return c
    if isinstance(c, list): return ''.join(b if isinstance(b, str) else (b or {}).get('text', '') for b in c)
    return ''


def raw_answer(conv):
    """The answer in the agent's last message (the harness rewrites it in place of the result)."""
    for call in conv.get('side_calls') or []:
        for m in call:
            t = text_of(m)
            if '## The answer the agent gave' in t:
                return t.split('## The answer the agent gave', 1)[1].split('## How the training memory spells answers', 1)[0].strip()
    for m in reversed(conv.get('messages') or []):
        t = text_of(m)
        if m.get('role') == 'assistant' and t.strip():
            span = adjudication.answer_span(t)
            return t[span[0]:span[1]] if span else t
    return None


def rewrites(conv):
    for call in conv.get('side_calls') or []:
        for m in call:
            if m.get('role') == 'assistant':
                pairs = adjudication.rewrites(text_of(m))
                if pairs:
                    return pairs
    return None


def msg(a):
    return json.dumps({"reasoning": "", "final_answer": a}, ensure_ascii=False)


total = collections.Counter()
for task in TASKS:
    path = f'{NEW}/{task}/memory.json'
    index = answer_space.build_index(path)
    conventions = answer_space.edge_conventions(answer_space.stored_values(path))
    per = collections.Counter()
    for row in (json.loads(l) for l in open(NEW + '/results/samples.jsonl')):
        if row['task'] != task:
            continue
        conv = json.load(open(f"{NEW}/{task}/conversations/{row['example_index']:04d}/sample-{row['sample_index']}.json"))
        raw = raw_answer(conv)
        if raw is None:
            per['no answer'] += 1
            continue
        answer, _ = adjudication.rewrite(raw, adjudication.accepted(rewrites(conv) or [], index[0]))
        answer, _ = answer_space.canonicalize(answer, index)
        answer, _ = answer_space.trim_trailing(answer, index, conventions)
        without = score(task, {'target': row['target']}, msg(answer), 'ok')['was_correct']
        completed, applied = answer_space.complete_compound(answer, index)
        with_ = score(task, {'target': row['target']}, msg(completed), 'ok')['was_correct'] if applied else without
        if applied:
            per['applied'] += applied
            if with_ and not without:
                per['win'] += 1
                print('WIN', task, row['example_index'], row['sample_index'], '|', answer, '->', completed, '| target', row['target'])
            elif without and not with_:
                per['loss'] += 1
                print('LOSS', task, row['example_index'], row['sample_index'], '|', answer, '->', completed, '| target', row['target'])
            else:
                per['nochange'] += 1
                print('NOCHANGE', task, row['example_index'], row['sample_index'], '|', answer, '->', completed, '| target', row['target'], '| correct', with_)
        per['replay correct'] += with_
        per['recorded correct'] += row['was_correct']
    print(task, dict(per))
    total.update(per)
print('TOTAL', dict(total))
PY
